head.script:
scwin.onpageload = function() {
    var jsonData = [{
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
    ];
    dataList1.setJSON(jsonData);
    localStorage.removeItem("log");	
};
scwin.onpageunload = function() {};
scwin.rowStatusClickFn = function(rowIndex) {
    console.log(rowIndex);
}
scwin.gridView1_onrowstatusclick = function(row) {
    //debugger;
    console.log(row);
};
scwin.gridView1_onrownumclick = function(row) {
    //debugger;
    console.log(row);
    localStorage.setItem("log", row);
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_headerRowNumber_bodyRow_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_headerRowNumber_bodyRow_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
